  title = 'UPSC Combined Defence Services Examination (CDS Exam II) Exam Pattern & Syllabus 2026: Marking Scheme, Topics & Cutoff Trends',
  slug = 'upsc-combined-defence-services-examination-cds-exam-ii-2026-2026-exam-pattern-selection',
